var i=`0455-lahmacun`;var t=`world-0455`;var a=`TR`;var o=`western-asia`;var l=8;var r=98;var s={en:`Lahmacun`,ua:`Лахмаджун`};var u={en:`A traditional dish from Türkiye, centered on all-purpose flour, instant yeast, ground lamb, tomato. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: пшеничне борошно універсальне, інстантні дріжджі, фарш з ягнятини, помідор. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,450,`g`],[`water`,240,`ml`],[`instant-yeast`,5,`g`],[`table-salt`,6,`g`],[`extra-virgin-olive-oil`,20,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`ground-lamb`,390,`g`],[`tomato`,250,`g`],[`yellow-onion`,150,`g`],[`parsley`,25,`g`],[`red-bell-pepper`,120,`g`],[`ground-cumin`,3,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 12 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 12 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:12,i:[]}];var d={slug:i,id:t,country:`TR`,region:o,servings:8,minutes:98,title:s,text:u,steps:g};export{a as country,d as default,t as id,r as minutes,o as region,l as servings,i as slug,g as steps,u as text,s as title};